		/**
		 * Returns a new populated Cart
		 * 
		 * @return Cart
		 */
		protected Cart generateNewEntity() {
			Cart entity = new Cart( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new Address(),  new Address(),  null,  null,  new HashSet<>(),  new HashSet<>(),  CartStatus.values()[0] );
			
			return( entity );
		}

